-- ============================================================
-- 称号Boss刷新坐标 (world.creature)
-- 来源：当前数据库 world.creature，id1 BETWEEN 430001 AND 430100
-- 用途：防止以后重新导入称号系统 SQL 时丢失或覆盖当前正确坐标
-- ============================================================

DELETE FROM `creature`
WHERE `id1` BETWEEN 430001 AND 430100
   OR `id2` BETWEEN 430001 AND 430100
   OR `id3` BETWEEN 430001 AND 430100
   OR `guid` BETWEEN 5400001 AND 5400100;

